def reflect(x, y, vx, paddle):
    ball = pygame.Rect(x - 6, y - 6, 12, 12)
    target = pygame.Rect(paddle)
    if ball.colliderect(target):
        if target.centerx < 320 and vx < 0:
            return target.right + 6, -vx
        if target.centerx >= 320 and vx > 0:
            return target.left - 6, -vx
    return x, vx

